import 'package:cloud_firestore/cloud_firestore.dart';import 'package:firebase_auth/firebase_auth.dart';import 'package:flutter/material.dart';
class SupportChatScreen extends StatefulWidget{final bool admin;final String? threadId;const SupportChatScreen({super.key,this.admin=false,this.threadId});@override State<SupportChatScreen> createState()=>_S();}
class _S extends State<SupportChatScreen>{final text=TextEditingController();String get uid=>FirebaseAuth.instance.currentUser!.uid;String get id=>widget.threadId??uid;Future<void> send()async{final v=text.text.trim();if(v.isEmpty)return;final r=FirebaseFirestore.instance.collection('support_threads').doc(id);await r.set({'userId':widget.admin?(widget.threadId??''):uid,'lastMessage':v,'lastMessageAt':FieldValue.serverTimestamp(),'unreadForAdmin':widget.admin?false:true,'unreadForUser':widget.admin?true:false,'status':'open'},SetOptions(merge:true));await r.collection('messages').add({'senderId':uid,'text':v,'createdAt':FieldValue.serverTimestamp()});text.clear();}Future<void> read()async{await FirebaseFirestore.instance.collection('support_threads').doc(id).update(widget.admin?{'unreadForAdmin':false}:{'unreadForUser':false});}@override Widget build(BuildContext c){read();return Scaffold(appBar:AppBar(title:Text(widget.admin?'Customer Support':'Bantuan Flowa')),body:Column(children:[Expanded(child:StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection('support_threads').doc(id).collection('messages').orderBy('createdAt',descending:true).snapshots(),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());return ListView(reverse:true,children:s.data!.docs.map((d){final x=d.data();return Align(alignment:x['senderId']==uid?Alignment.centerRight:Alignment.centerLeft,child:Padding(padding:const EdgeInsets.all(8),child:Text(x['text']??'')));}).toList());})),Row(children:[Expanded(child:TextField(controller:text,decoration:const InputDecoration(hintText:'Tulis pesan ke Customer Service'))),IconButton(onPressed:send,icon:const Icon(Icons.send))]) ]));}}